{
  "technical_and_design_decisions": [
    "Adopt Go modules as the externalization mechanism; each required component (gossip protoext, cauthdsl, ccprovider, ledger, common/core utilities, configtxgen, configtxlator) will be extracted into a separate Go module with its own go.mod and semantic versioning.",
    "Preserve existing exported APIs of the copied code to minimize downstream changes; only packaging and import paths will change, plus minimal shims if needed.",
    "Implement the U6 temporary workaround inside the chaincode packaging logic to honor an embedded go.mod file, with a deprecation log warning and a scheduled removal milestone.",
    "Use automated refactoring (goimports, find/replace) plus manual compilation fixes to update SDK imports to the new external modules.",
    "External modules will be placed under a dedicated namespace (e.g., github.com/hyperledger/fabric-common) to avoid circular dependencies with the main Fabric monorepo."
  ],
  "assumptions": [
    "A single developer with working knowledge of both Hyperledger Fabric and Fabric Go SDK codebases performs all tasks.",
    "The externalized modules are permitted to be published within the Hyperledger GitHub organization and consumed by the SDK via go.mod.",
    "The SDK's current internal copies contain only minor SDK-specific modifications that can be generalized or absorbed without new features.",
    "Existing unit and integration tests in both repositories are adequate to verify functional equivalence after refactoring.",
    "Effort includes local build, test, and fix cycles but excludes external code review wait times, lengthy CI queue times, and project management overhead.",
    "The U6 workaround is implemented as a short-lived feature and will be removed in a later release; this estimate covers only its initial implementation."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Analysis and design",
      "activity_description": "Analyze current copied/modified code in Fabric SDK and Fabric for all user stories (U1-U8), define module boundaries, and design the externalization and migration approach.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A2",
      "activity_name": "Externalize gossip protoext",
      "activity_description": "Extract gossip utilities protoext (including the modified discovery client copy) from Fabric into a separate Go module, adjust internal imports, add go.mod, and verify it builds independently (U1).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A3",
      "activity_name": "Externalize cauthdsl utilities",
      "activity_description": "Extract cauthdsl utilities from Fabric common into an external Go module consumable by SDK and client apps (U2).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A4",
      "activity_name": "Externalize ccprovider structures",
      "activity_description": "Extract ccprovider structures from Fabric core/common into an external Go module (U3).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A5",
      "activity_name": "Externalize ledger structures",
      "activity_description": "Extract the useful ledger structures from Fabric core/ledger into an external Go module suitable for SDK usage (U4).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A6",
      "activity_name": "Externalize common and core utilities",
      "activity_description": "Extract remaining common and core utilities currently copied in SDK internal directories into external modules (U5).",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A7",
      "activity_name": "Externalize configtxgen functions",
      "activity_description": "Extract configtxgen functions from Fabric and SDK internal copies into an external module (U7).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A8",
      "activity_name": "Externalize configtxlator functions",
      "activity_description": "Extract configtxlator functions from SDK internal copies into an external module (U8).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A9",
      "activity_name": "Temporary go.mod workaround",
      "activity_description": "Implement short-lived logic in the chaincode packaging tooling to honor go.mod files inside chaincode packages, with deprecation logging (U6).",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A10",
      "activity_name": "Update SDK to consume external modules",
      "activity_description": "Remove internal copied directories from Fabric Go SDK, update SDK go.mod with required modules, and rewrite import paths across the SDK codebase; fix compilation errors.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A11",
      "activity_name": "Integration testing and defect fixing",
      "activity_description": "Build the SDK and external modules, execute unit/integration tests, and fix defects caused by externalization or import changes.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A12",
      "activity_name": "Documentation and migration guide",
      "activity_description": "Update SDK and module documentation, README, and provide a migration guide for users moving from copied code to external modules; note temporary workaround.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A13",
      "activity_name": "Release preparation and versioning",
      "activity_description": "Tag external modules, bump SDK version, update CI configurations to build/test new modules, and prepare release notes.",
      "most_likely_effort": 12
    }
  ],
  "reported_total": {
    "most_likely_effort": 320
  }
}

